-- Du lieu Kham pha cong khai: 1156 dia diem va 1202 muc tra cuu (diem den, khu vuc, dia diem, cam nang, di chuyen).
-- Sinh tu dong boi tools/export-places/export.cjs ngay 2026-11-17. Khong sua tay: chay lai cong cu de cap nhat.
-- Nap mot lan tren co so du lieu moi (danh dau bang extended property). Bo qua dia diem trung ten + khu vuc va muc trung Slug,
-- nen chay tren co so du lieu da co du lieu cung khong tao ban sao.
SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET XACT_ABORT ON; SET NOCOUNT ON;
IF OBJECT_ID(N'dbo.DiscoveryEntry',N'U') IS NOT NULL AND OBJECT_ID(N'dbo.DiaDiemDuLich',N'U') IS NOT NULL AND OBJECT_ID(N'dbo.DonViHanhChinh',N'U') IS NOT NULL
AND NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'HanhTrinh.DuLieuKhamPha' AND CAST(value AS nvarchar(20))=N'v1')
BEGIN
 BEGIN TRANSACTION;
 CREATE TABLE #p(Ten nvarchar(200) COLLATE DATABASE_DEFAULT,Loai nvarchar(100) COLLATE DATABASE_DEFAULT,Vung nvarchar(200) COLLATE DATABASE_DEFAULT,DiaChi nvarchar(500) COLLATE DATABASE_DEFAULT,MoTa nvarchar(max) COLLATE DATABASE_DEFAULT,Hien bit,Regime varchar(10) COLLATE DATABASE_DEFAULT,Code varchar(20) COLLATE DATABASE_DEFAULT);
