 INSERT dbo.DiaDiemDuLich(TenDiaDiem,LoaiDiaDiem,KhuVuc,DiaChi,MoTa,DangHienThi,DonViId)
  SELECT p.Ten,p.Loai,p.Vung,p.DiaChi,p.MoTa,p.Hien,d.Id FROM #p p LEFT JOIN dbo.DonViHanhChinh d ON d.Regime=p.Regime AND d.Code=p.Code
  WHERE NOT EXISTS (SELECT 1 FROM dbo.DiaDiemDuLich x WHERE x.TenDiaDiem=p.Ten AND x.KhuVuc=p.Vung);
 CREATE TABLE #e(Slug varchar(160) COLLATE DATABASE_DEFAULT,Kind varchar(25) COLLATE DATABASE_DEFAULT,ParentSlug varchar(160) COLLATE DATABASE_DEFAULT,PlaceTen nvarchar(200) COLLATE DATABASE_DEFAULT,PlaceVung nvarchar(200) COLLATE DATABASE_DEFAULT,Title nvarchar(200) COLLATE DATABASE_DEFAULT,Region nvarchar(100) COLLATE DATABASE_DEFAULT,Summary nvarchar(700) COLLATE DATABASE_DEFAULT,Body nvarchar(max) COLLATE DATABASE_DEFAULT,Address nvarchar(500) COLLATE DATABASE_DEFAULT,Lat decimal(9,6),Lng decimal(9,6),LocationNote nvarchar(500) COLLATE DATABASE_DEFAULT,SourceName nvarchar(300) COLLATE DATABASE_DEFAULT,SourceUrl nvarchar(500) COLLATE DATABASE_DEFAULT,CheckedOn date,ValidFrom date,ValidTo date,PriceFrom decimal(18,2),PriceTo decimal(18,2),PriceUnit nvarchar(100) COLLATE DATABASE_DEFAULT,Includes nvarchar(max) COLLATE DATABASE_DEFAULT,Excludes nvarchar(max) COLLATE DATABASE_DEFAULT,Hours nvarchar(700) COLLATE DATABASE_DEFAULT,OpenDays varchar(50) COLLATE DATABASE_DEFAULT,OpenTime time,CloseTime time,DurationMinutes int,Tags nvarchar(1000) COLLATE DATABASE_DEFAULT,TransportMode varchar(50) COLLATE DATABASE_DEFAULT,Origin nvarchar(200) COLLATE DATABASE_DEFAULT,Destination nvarchar(200) COLLATE DATABASE_DEFAULT,Contact nvarchar(300) COLLATE DATABASE_DEFAULT,Status varchar(20) COLLATE DATABASE_DEFAULT,AttributesJson nvarchar(max) COLLATE DATABASE_DEFAULT,ImagePath nvarchar(300) COLLATE DATABASE_DEFAULT,Regime varchar(10) COLLATE DATABASE_DEFAULT,Code varchar(20) COLLATE DATABASE_DEFAULT);
 INSERT #e VALUES
  ('place-1','Place',NULL,N'Đồi chè Cầu Đất',N'Đà Lạt',N'Đồi chè Cầu Đất',N'Đà Lạt',N'Những triền đồi xanh nối tiếp trong sương sớm. Thời gian tham quan gợi ý: 05:30–09:00.',N'',NULL,NULL,NULL,NULL,N'Thông tin đã công bố trong hệ thống',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'Thiên nhiên',NULL,NULL,NULL,NULL,'Published',NULL,NULL,'Cu','672'),
  ('place-3','Place',NULL,N'Vịnh Lan Hạ',N'Hải Phòng',N'Vịnh Lan Hạ',N'Hải Phòng',N'Khám phá mặt nước xanh, đảo đá và nhịp sống làng chài.',N'',NULL,NULL,NULL,NULL,N'Thông tin đã công bố trong hệ thống',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'Thiên nhiên',NULL,NULL,NULL,NULL,'Published',NULL,NULL,'Cu','31'),
  ('destination-da-lat','Destination',NULL,NULL,NULL,N'Đà Lạt',N'Đà Lạt',N'Khám phá địa điểm, dịch vụ và thông tin cần biết cho chuyến đi tại khu vực Đà Lạt.',N'Bắt đầu từ những nơi bạn muốn ghé, sau đó xem khoảng cách và cách di chuyển giữa chúng. Kiểm tra giá, đơn vị tính và thời gian phục vụ ở từng địa điểm.

Tọa độ trên bản đồ là mốc tham chiếu khu vực, không phải lối vào một điểm tham quan. Chọn địa điểm hoặc ghim cụ thể khi tính tuyến.',NULL,11.94646,108.44193,N'Mốc tham chiếu khu vực theo UNT Digital Library; không phải lối vào.',N'UNT Digital Library — tọa độ địa danh Đà Lạt',N'https://digital.library.unt.edu/explore/locations/p19502/','2026-11-08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'thiên nhiên cà phê tham quan lưu trú khám phá',NULL,NULL,NULL,NULL,'Published',NULL,NULL,'Cu','672'),
  ('guide-vietnam-transport','Transport',NULL,NULL,NULL,N'Tìm hiểu cách di chuyển khi du lịch tự túc',N'Việt Nam',N'Tra cứu các phương án đường hàng không, tàu và đường bộ; kiểm tra lịch, điểm đón trả và điều kiện hành lý trước khi chọn.',N'So sánh điểm xuất phát và điểm đến thực tế, đoạn đi tiếp sau khi xuống phương tiện, thời gian chờ và đổi chặng. Kiểm tra giá và lịch tại đơn vị vận hành trước khi mua vé.

Chức năng tính tuyến trên bản đồ cung cấp tham khảo cho ô tô, đi bộ và xe đạp. Lịch tàu, xe buýt và giá vé cần đối chiếu nguồn của đơn vị khai thác; không suy ra từ tuyến đường bộ.',NULL,NULL,NULL,NULL,N'Vietnam Tourism — Transport within Vietnam',N'https://vietnam.travel/plan-your-trip/transport-within-vietnam/','2026-11-08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'di chuyển đi lại tàu xe buýt sân bay bến xe phương tiện hành lý','Mixed',N'Chọn nơi xuất phát',N'Chọn điểm đến',NULL,'Published',NULL,NULL,NULL,NULL),
  ('guide-weather','Guide',NULL,NULL,NULL,N'Tìm hiểu thời tiết theo mùa trước khi đi',N'Việt Nam',N'Tham khảo đặc điểm khí hậu theo vùng, rồi kiểm tra dự báo gần ngày đi và thông báo của điểm đến.',N'Thông tin khí hậu theo mùa giúp chuẩn bị phương án trải nghiệm. Dự báo thời tiết là thông tin theo thời điểm và cần kiểm tra lại gần ngày đi.

Khi muốn tìm trải nghiệm trong nhà, chọn bộ lọc Trong nhà. Những nơi chưa có thông tin xác nhận sẽ không được tính là đáp ứng điều kiện này.',NULL,NULL,NULL,NULL,N'Vietnam Tourism — Weather and climate in Vietnam',N'https://vietnam.travel/things-to-do/weather-and-climate-vietnam/','2026-11-08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'thời tiết trời mưa trong nhà mùa khí hậu dự báo',NULL,NULL,NULL,NULL,'Published',NULL,NULL,NULL,NULL),
  ('guide-events','Guide',NULL,NULL,NULL,N'Tra cứu lễ hội và sự kiện theo thời gian',N'Việt Nam',N'Tìm lịch công bố của đơn vị tổ chức và kiểm tra lại ngày, địa điểm, vé hoặc yêu cầu đăng ký.',N'Mở nhóm Sự kiện, chọn ngày dự định tham gia để xem các sự kiện đã công bố trên hệ thống. Khi chưa có kết quả, bạn có thể đối chiếu lịch của Vietnam Tourism tại nguồn bên dưới.

Một mục lịch tổng hợp không xác nhận còn vé hay việc sự kiện chắc chắn diễn ra. Kiểm tra thông báo mới nhất của đơn vị tổ chức trước khi đến.',NULL,NULL,NULL,NULL,N'Vietnam Tourism — Festivals & events',N'https://vietnam.travel/event/','2026-11-08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'lễ hội sự kiện hôm nay cuối tuần lịch hoạt động',NULL,NULL,NULL,NULL,'Published',NULL,NULL,NULL,NULL),
  ('guide-accessibility','Guide',NULL,NULL,NULL,N'Kiểm tra khả năng tiếp cận của địa điểm',N'Việt Nam',N'Tìm thông tin cụ thể về lối vào, nhà vệ sinh, chỗ ngồi và bãi đỗ xe trước khi chọn địa điểm.',N'Chọn từng điều kiện bạn cần trong bộ lọc tiện ích. Kết quả chỉ đáp ứng khi thuộc tính được xác nhận có; dữ liệu còn thiếu được ghi rõ.

Với yêu cầu cụ thể như chiều rộng lối vào hoặc việc sử dụng xe lăn, hãy hỏi đơn vị vận hành tại mục Hỏi đáp trước khi quyết định. Khả năng tiếp cận cần được kiểm tra cho cả lối vào và không gian sử dụng.',NULL,NULL,NULL,NULL,N'Google Maps Help — Accessibility information',N'https://support.google.com/maps/answer/6396990','2026-11-08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'tiếp cận xe lăn người lớn tuổi trẻ em bậc thang nhà vệ sinh lối vào',NULL,NULL,NULL,NULL,'Published',NULL,NULL,NULL,NULL),
  ('destination-hoi-an','Destination',NULL,NULL,NULL,N'Hội An',N'Hội An',N'Tìm hiểu phố cổ, các khu vực xung quanh và thông tin thực tế trước khi ghé thăm.',N'Phố cổ Hội An là di sản được UNESCO ghi danh. Tìm địa điểm và dịch vụ theo khu vực, sau đó kiểm tra vị trí, điều kiện tiếp cận và thông tin phục vụ.

Mốc bản đồ lấy theo hồ sơ di sản; khi tính đường đi hãy chọn đúng lối tiếp cận. Giá vé và giờ tham quan cần được xác nhận từ đơn vị quản lý.',NULL,15.883333,108.333333,N'Mốc tham chiếu khu di sản theo UNESCO; không xác nhận lối vào.',N'UNESCO World Heritage Centre — Hoi An Ancient Town',N'https://whc.unesco.org/en/list/948/','2026-11-08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'phố cổ văn hóa di sản tham quan đi bộ',NULL,NULL,NULL,NULL,'Published',NULL,NULL,'Cu','503'),
  ('demo-danang-destination','Destination',NULL,NULL,NULL,N'Đà Nẵng',N'Đà Nẵng',N'Thành phố biển ở miền Trung, gần Hội An và Huế; có biển, núi, di sản và nhiều món ăn địa phương.',N'Đà Nẵng nằm ven biển miền Trung. Du khách thường kết hợp tắm biển, tham quan các điểm trên núi và bán đảo, ghé chợ truyền thống và thử món địa phương, rồi đi tiếp tới Hội An hoặc Huế.

Trang này gom các mục đã công bố theo khu vực. Hãy chọn từng quận, huyện để thu hẹp.

Giá vé, giờ mở cửa và điều kiện tiếp cận chưa có thông tin xác nhận; kiểm tra với đơn vị quản lý trước khi đi.',NULL,16.0544,108.2022,N'Mốc trung tâm thành phố, không phải một địa điểm cụ thể.',N'Dữ liệu mẫu do hệ thống soạn từ kiến thức phổ biến, chưa kiểm chứng tại chỗ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,N'Điểm đến thành phố biển',NULL,NULL,NULL,NULL,'Published',NULL,NULL,'Cu','48'),
